-- Appointments are generated at startup rather than stored in the backup, so they're always in the future.
-- Safe to run against a backup that already contains the table: nothing is inserted if it has rows.

CREATE TABLE IF NOT EXISTS public."Appointments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PetId" integer NOT NULL,
    "VeterinarianId" integer NOT NULL,
    "ScheduledAt" timestamp with time zone NOT NULL,
    "RequestedAt" timestamp with time zone NOT NULL,
    "Reason" text NOT NULL,
    "Status" text NOT NULL,
    CONSTRAINT "PK_Appointments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Appointments_Pets_PetId" FOREIGN KEY ("PetId") REFERENCES public."Pets" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Appointments_Veterinarians_VeterinarianId" FOREIGN KEY ("VeterinarianId") REFERENCES public."Veterinarians" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_Appointments_PetId" ON public."Appointments" ("PetId");
CREATE INDEX IF NOT EXISTS "IX_Appointments_VeterinarianId" ON public."Appointments" ("VeterinarianId");
CREATE INDEX IF NOT EXISTS "IX_Appointments_Status_ScheduledAt" ON public."Appointments" ("Status", "ScheduledAt");

SELECT setseed(0.42);

-- About one in five pets has an appointment in the next 60 days, on the hour or half hour between
-- 14:00 and 23:30 UTC (8:00-17:30 US Central). Roughly 70% are confirmed and 30% are still pending.
INSERT INTO public."Appointments" ("PetId", "VeterinarianId", "ScheduledAt", "RequestedAt", "Reason", "Status")
SELECT p."Id",
       1 + floor(random() * (SELECT max("Id") FROM public."Veterinarians"))::int,
       date_trunc('day', now())
           + (1 + floor(random() * 60)) * interval '1 day'
           + (14 + floor(random() * 10)) * interval '1 hour'
           + floor(random() * 2) * interval '30 minutes',
       now() - random() * interval '30 days',
       (ARRAY['Annual checkup', 'Vaccination', 'Dental cleaning', 'Follow-up', 'Skin irritation', 'Limping', 'Ear infection'])[1 + floor(random() * 7)::int],
       CASE WHEN random() < 0.7 THEN 'Confirmed' ELSE 'Pending' END
FROM public."Pets" p
WHERE random() < 0.2
  AND NOT EXISTS (SELECT 1 FROM public."Appointments");

ANALYZE public."Appointments";
